"use client";

/* eslint-disable jsx-a11y/no-static-element-interactions, jsx-a11y/no-noninteractive-element-interactions */

import { type ReactNode, useEffect, useState } from "react";

type RiverSegment = { id:string; name:string; basin:string; classRef:string; targetClass:string; condition:"Conforme"|"Atenção"|"Não conforme"; iqa:number; trend:"Melhorando"|"Estável"|"Piorando"; confidence:number; pressure:string; population:string; center:[number,number] };
type Sample = { id:string; stationId:string; segmentId:string; collectedAt:string; lab:string; method:string; parameter:string; observed:number; unit:string; limit:number; uncertainty:string; quality:number; status:"Recebida"|"Em QA/QC"|"Qualificada"|"Revisão humana" };
type Discharge = { id:string; name:string; segmentId:string; holder:string; permit:string; authorizedFlow:number; observedFlow:number; authorizedLoad:number; observedLoad:number; treatment:string; status:"Regular"|"Atenção"|"Revisão" };
type Pressure = { id:string; type:string; source:string; territory:string; score:number; confidence:number; load:string; trend:"Crescente"|"Estável"|"Decrescente"; status:"Crítica"|"Alta"|"Moderada" };
type QualityTarget = { id:string; segmentId:string; parameter:string; baseline:number; current:number; target:number; unit:string; due:string; source:string; progress:number; status:"No prazo"|"Atenção"|"Em risco" };
type RecoveryMeasure = { id:string; title:string; segmentId:string; kind:string; owner:string; cost:number; benefit:number; progress:number; priority:"P1"|"P2"|"P3"; status:"Proposta"|"Em pactuação"|"Em execução"|"Verificação"; evidence:string };
type WaterQualityHubProps = { contextItem:string; territory:string; clockLabel:string; onNavigate:(item:string)=>void; onOpenModule:(moduleId:string)=>void; onToast:(message:string)=>void };

const initialSegments:RiverSegment[]=[
  {id:"TRC-SF-0418",name:"Rio das Velhas · trecho 0418",basin:"São Francisco · Alto",classRef:"Classe 2",targetClass:"Classe 2 · 2030",condition:"Não conforme",iqa:48,trend:"Piorando",confidence:94,pressure:"esgoto urbano + carga difusa",population:"2,1 mi",center:[-44.02,-19.82]},
  {id:"TRC-PCJ-0087",name:"Rio Atibaia · trecho 0087",basin:"PCJ · SP",classRef:"Classe 2",targetClass:"Classe 2 · mantida",condition:"Atenção",iqa:61,trend:"Estável",confidence:92,pressure:"lançamentos industriais",population:"1,4 mi",center:[-46.84,-22.89]},
  {id:"TRC-PRB-0124",name:"Rio Descoberto · trecho 0124",basin:"Paranaíba · DF",classRef:"Classe 2",targetClass:"Classe 1 · 2032",condition:"Conforme",iqa:79,trend:"Melhorando",confidence:96,pressure:"uso urbano + agricultura",population:"680 mil",center:[-48.18,-15.72]},
  {id:"TRC-ITA-0033",name:"Rio Itajaí-Açu · trecho 0033",basin:"Itajaí · SC",classRef:"Classe 2",targetClass:"Classe 2 · 2028",condition:"Atenção",iqa:66,trend:"Melhorando",confidence:88,pressure:"turbidez pós-cheia",population:"420 mil",center:[-49.08,-26.92]},
];
const initialSamples:Sample[]=[
  {id:"AMO-RNQA-260810-1842",stationId:"RNQA-MG-0174",segmentId:"TRC-SF-0418",collectedAt:"10 ago · 08:15",lab:"Laboratório ANA · MG",method:"SM 4500-O G",parameter:"Oxigênio dissolvido",observed:3.6,unit:"mg/L",limit:5,uncertainty:"±0,18",quality:96,status:"Revisão humana"},
  {id:"AMO-RNQA-260809-1791",stationId:"CETESB-ATB-09",segmentId:"TRC-PCJ-0087",collectedAt:"09 ago · 14:40",lab:"CETESB · Campinas",method:"SM 9223 B",parameter:"E. coli",observed:1180,unit:"NMP/100mL",limit:1000,uncertainty:"±7%",quality:92,status:"Qualificada"},
  {id:"AMO-RNQA-260808-1688",stationId:"ADASA-DES-04",segmentId:"TRC-PRB-0124",collectedAt:"08 ago · 09:20",lab:"LACEN-DF",method:"SM 4500-P E",parameter:"Fósforo total",observed:.071,unit:"mg/L",limit:.1,uncertainty:"±0,006",quality:97,status:"Qualificada"},
  {id:"AMO-RNQA-260810-1856",stationId:"IMA-ITA-11",segmentId:"TRC-ITA-0033",collectedAt:"10 ago · 07:55",lab:"IMA-SC",method:"SM 2130 B",parameter:"Turbidez",observed:114,unit:"NTU",limit:100,uncertainty:"±4,2",quality:89,status:"Em QA/QC"},
];
const initialDischarges:Discharge[]=[
  {id:"LAN-MG-00741",name:"ETE Arrudas · lançamento final",segmentId:"TRC-SF-0418",holder:"COPASA",permit:"OUT-MG-2022-8841",authorizedFlow:2400,observedFlow:2528,authorizedLoad:1880,observedLoad:2314,treatment:"secundário + desinfecção",status:"Revisão"},
  {id:"LAN-SP-01892",name:"Distrito industrial Atibaia",segmentId:"TRC-PCJ-0087",holder:"Consórcio DI-Atibaia",permit:"OUT-SP-2024-1918",authorizedFlow:318,observedFlow:302,authorizedLoad:422,observedLoad:438,treatment:"físico-químico",status:"Atenção"},
  {id:"LAN-DF-00127",name:"ETE Melchior · contribuição indireta",segmentId:"TRC-PRB-0124",holder:"CAESB",permit:"OUT-DF-2023-117",authorizedFlow:1500,observedFlow:1422,authorizedLoad:980,observedLoad:904,treatment:"terciário",status:"Regular"},
];
const initialPressures:Pressure[]=[
  {id:"PRS-URB-041",type:"Pontual",source:"Esgotamento sanitário",territory:"RMBH · 18 sub-bacias",score:92,confidence:94,load:"2,31 t DBO/d",trend:"Crescente",status:"Crítica"},
  {id:"PRS-DIF-083",type:"Difusa",source:"Agricultura e solo exposto",territory:"BHO6 · 6.840 km²",score:78,confidence:82,load:"0,84 t P/d",trend:"Crescente",status:"Alta"},
  {id:"PRS-IND-026",type:"Pontual",source:"Efluente industrial",territory:"PCJ · 41 fontes",score:72,confidence:91,load:"0,46 t DQO/d",trend:"Estável",status:"Alta"},
  {id:"PRS-MIN-012",type:"Acidental",source:"Mineração e sedimentos",territory:"Alto São Francisco",score:61,confidence:76,load:"pressão potencial",trend:"Decrescente",status:"Moderada"},
];
const initialTargets:QualityTarget[]=[
  {id:"META-QA-011",segmentId:"TRC-SF-0418",parameter:"Oxigênio dissolvido",baseline:3.1,current:3.6,target:5,unit:"mg/L",due:"dez 2030",source:"Plano de bacia · Meta Q4",progress:38,status:"Em risco"},
  {id:"META-QA-014",segmentId:"TRC-SF-0418",parameter:"DBO 5,20",baseline:8.8,current:7.2,target:5,unit:"mg/L",due:"dez 2030",source:"Enquadramento progressivo",progress:42,status:"Em risco"},
  {id:"META-QA-021",segmentId:"TRC-PCJ-0087",parameter:"E. coli",baseline:1980,current:1180,target:1000,unit:"NMP/100mL",due:"jun 2028",source:"Plano PCJ · programa 2",progress:82,status:"Atenção"},
  {id:"META-QA-037",segmentId:"TRC-PRB-0124",parameter:"Fósforo total",baseline:.11,current:.071,target:.05,unit:"mg/L",due:"dez 2032",source:"PERH-DF · meta 7",progress:66,status:"No prazo"},
];
const initialMeasures:RecoveryMeasure[]=[
  {id:"MED-REC-0041",title:"Otimizar remoção de carga na ETE Arrudas",segmentId:"TRC-SF-0418",kind:"Saneamento",owner:"COPASA + municípios",cost:184.6,benefit:91,progress:24,priority:"P1",status:"Em pactuação",evidence:"CEN-QA-2026-018 · redução estimada 31%"},
  {id:"MED-REC-0053",title:"Infraestrutura verde em 12 microbacias",segmentId:"TRC-SF-0418",kind:"Carga difusa",owner:"CBH Velhas + prefeituras",cost:42.8,benefit:76,progress:12,priority:"P1",status:"Proposta",evidence:"Living Atlas + CAR · 418 áreas"},
  {id:"MED-REC-0068",title:"Reconversão de faixa ripária prioritária",segmentId:"TRC-PCJ-0087",kind:"Restauração",owner:"Agência PCJ",cost:28.4,benefit:72,progress:58,priority:"P2",status:"Em execução",evidence:"M7 · 72% cobertura confirmada"},
  {id:"MED-REC-0074",title:"Rede sentinela e resposta a turbidez",segmentId:"TRC-ITA-0033",kind:"Monitoramento",owner:"IMA + municípios",cost:8.9,benefit:68,progress:81,priority:"P2",status:"Verificação",evidence:"M9 · INC-2026-0084"},
];
const statusClass=(value:string)=>value.toLowerCase().replaceAll(" ","-").normalize("NFD").replace(/[\u0300-\u036f]/g,"");

export function WaterQualityHub({contextItem,territory,clockLabel,onNavigate,onOpenModule,onToast}:WaterQualityHubProps){
  const [segments]=useState(initialSegments); const [selectedSegmentId,setSelectedSegmentId]=useState(initialSegments[0].id);
  const [samples,setSamples]=useState(initialSamples); const [selectedSampleId,setSelectedSampleId]=useState(initialSamples[0].id);
  const [discharges,setDischarges]=useState(initialDischarges); const [selectedDischargeId,setSelectedDischargeId]=useState(initialDischarges[0].id);
  const [pressures]=useState(initialPressures); const [targets,setTargets]=useState(initialTargets); const [measures,setMeasures]=useState(initialMeasures);
  const [sampleModalOpen,setSampleModalOpen]=useState(false); const [framingModalOpen,setFramingModalOpen]=useState(false); const [dischargeModalOpen,setDischargeModalOpen]=useState(false); const [recoveryModalOpen,setRecoveryModalOpen]=useState(false);
  const [agentOpen,setAgentOpen]=useState(false); const [agentRunning,setAgentRunning]=useState(false); const [agentStep,setAgentStep]=useState(6); const [liveTick,setLiveTick]=useState(0);
  const [dataContext,setDataContext]=useState({seriesId:"SER-RNQA-MG-0174-Q",stationId:"RNQA-MG-0174",quality:96,version:"qv.23"});
  const [regulationContext,setRegulationContext]=useState({demandId:"DEM-2026-1842",authorizedFlow:2400,authority:"ANA + IGAM · competência contextual"});
  const [scenarioContext,setScenarioContext]=useState({scenarioId:"CEN-QA-2026-018",reliability:91,balance:4.8,modelId:"MOD-WASP-BHO6-014"});
  const [planningContext,setPlanningContext]=useState({planId:"PLAN-SF-2022-2032",actionId:"ACT-QA-0041",projectId:"PRJ-SAN-041",budget:184.6,progress:24});
  const [fieldContext,setFieldContext]=useState({evidenceId:"EVD-GF-11842",caseId:"GF-2026-0914",status:"Verificada"});
  const [incidentContext,setIncidentContext]=useState({incidentId:"INC-2026-0084",type:"Qualidade",level:"N1",status:"Estabilização"});
  const selectedSegment=segments.find(item=>item.id===selectedSegmentId)??segments[0]; const selectedSample=samples.find(item=>item.id===selectedSampleId)??samples[0]; const selectedDischarge=discharges.find(item=>item.id===selectedDischargeId)??discharges[0];

  useEffect(()=>{const timer=window.setInterval(()=>setLiveTick(value=>(value+1)%12),1800);return()=>window.clearInterval(timer);},[]);
  useEffect(()=>{
    const data=(event:Event)=>{const detail=(event as CustomEvent<typeof dataContext>).detail;if(detail?.seriesId)setDataContext(value=>({...value,...detail}));};
    const regulation=(event:Event)=>{const detail=(event as CustomEvent<typeof regulationContext>).detail;if(detail?.demandId)setRegulationContext(value=>({...value,...detail}));};
    const scenario=(event:Event)=>{const detail=(event as CustomEvent<typeof scenarioContext>).detail;if(detail?.scenarioId)setScenarioContext(value=>({...value,...detail}));};
    const planning=(event:Event)=>{const detail=(event as CustomEvent<typeof planningContext>).detail;if(detail?.planId)setPlanningContext(value=>({...value,...detail}));};
    const field=(event:Event)=>{const detail=(event as CustomEvent<typeof fieldContext>).detail;if(detail?.evidenceId)setFieldContext(value=>({...value,...detail}));};
    const incident=(event:Event)=>{const detail=(event as CustomEvent<typeof incidentContext>).detail;if(detail?.incidentId)setIncidentContext(value=>({...value,...detail}));};
    window.addEventListener("cht:data-context",data);window.addEventListener("cht:regulation-context",regulation);window.addEventListener("cht:scenario-context",scenario);window.addEventListener("cht:planning-context",planning);window.addEventListener("cht:field-evidence-event",field);window.addEventListener("cht:critical-event-context",incident);
    return()=>{window.removeEventListener("cht:data-context",data);window.removeEventListener("cht:regulation-context",regulation);window.removeEventListener("cht:scenario-context",scenario);window.removeEventListener("cht:planning-context",planning);window.removeEventListener("cht:field-evidence-event",field);window.removeEventListener("cht:critical-event-context",incident);};
  },[]);
  useEffect(()=>{if(!agentRunning)return;const timer=window.setInterval(()=>setAgentStep(step=>{if(step>=6){setAgentRunning(false);onToast("Análise de qualidade concluída; achados e medidas aguardam validação humana.");return step;}return step+1;}),820);return()=>window.clearInterval(timer);},[agentRunning,onToast]);

  const broadcastQuality=()=>window.dispatchEvent(new CustomEvent("cht:water-quality-context",{detail:{segmentId:selectedSegment.id,classRef:selectedSegment.classRef,targetClass:selectedSegment.targetClass,condition:selectedSegment.condition,iqa:selectedSegment.iqa,confidence:selectedSegment.confidence,stationId:selectedSample.stationId,center:selectedSegment.center}}));
  const emitTower=(title:string,severity:"Crítico"|"Alto"|"Médio"|"Baixo",recommendation:string)=>window.dispatchEvent(new CustomEvent("cht:module-event",{detail:{eventId:`WQE-${selectedSegment.id}-${clockLabel.replaceAll(":","")}`,type:"quality.water.assessment",title,severity,source:"M10 · Qualidade da Água",module:"m10",moduleName:"Qualidade da Água",territory:selectedSegment.basin,confidence:selectedSegment.confidence,chtId:selectedSegment.id,recommendation,occurredAt:clockLabel}}));
  const focusSegment=(item:RiverSegment)=>{setSelectedSegmentId(item.id);window.dispatchEvent(new CustomEvent("cht:focus-map",{detail:{center:item.center,zoom:9,label:item.name,source:`${item.id} · ${item.classRef}`,confidence:item.confidence}}));window.dispatchEvent(new CustomEvent("cht:water-quality-context",{detail:{segmentId:item.id,classRef:item.classRef,targetClass:item.targetClass,condition:item.condition,iqa:item.iqa,confidence:item.confidence,center:item.center}}));};
  const openConsumer=(moduleId:string)=>{broadcastQuality();onOpenModule(moduleId);};
  const startAgent=()=>{setAgentOpen(true);setAgentStep(0);setAgentRunning(true);};
  const requestQualityData=()=>{window.dispatchEvent(new CustomEvent("cht:quality-data-request",{detail:{segmentId:selectedSegment.id,targetId:"META-QA-011",stationId:selectedSample.stationId,parameters:["OD","DBO","E. coli","fósforo total","turbidez"],cadence:"semanal + evento",qualityFloor:90,reason:"Medir condição, tendência e efetividade da recuperação",territory:selectedSegment.basin,center:selectedSegment.center}}));onToast(`${selectedSegment.id}: contrato de monitoramento enviado ao M5.`);};
  const requestQualityScenario=()=>{window.dispatchEvent(new CustomEvent("cht:quality-scenario-request",{detail:{segmentId:selectedSegment.id,scenarioId:scenarioContext.scenarioId,modelId:scenarioContext.modelId,sources:pressures.map(item=>item.id),baselineLoad:selectedDischarge.observedLoad,reductionTarget:31,horizon:"2026–2032",territory:selectedSegment.basin,center:selectedSegment.center,requestedBy:"M10 · Agente de Recuperação"}}));onToast(`${selectedSegment.id}: cenário de cargas e medidas solicitado ao M6.`);};
  const qualifySample=()=>{setSamples(items=>items.map(item=>item.id===selectedSample.id?{...item,status:"Qualificada",quality:98}:item));setSampleModalOpen(false);emitTower("Amostra qualificada com desconformidade contextual","Alto",`${selectedSample.parameter} requer correlação com fontes, série e regra do enquadramento.`);onToast(`${selectedSample.id} qualificada por revisão humana; bruto, método e incerteza preservados.`);};
  const reviewFraming=()=>{setFramingModalOpen(false);emitTower("Gap de enquadramento validado","Alto",`${selectedSegment.id} permanece em acompanhamento para alcançar ${selectedSegment.targetClass}.`);onToast("Revisão humana registrada; o enquadramento oficial não foi alterado pelo mockup.");};
  const reconcileDischarge=()=>{setDischarges(items=>items.map(item=>item.id===selectedDischarge.id?{...item,status:"Atenção"}:item));setDischargeModalOpen(false);window.dispatchEvent(new CustomEvent("cht:quality-regulatory-review-event",{detail:{segmentId:selectedSegment.id,dischargeId:selectedDischarge.id,demandId:regulationContext.demandId,permit:selectedDischarge.permit,title:"Revisar carga observada e condicionantes do lançamento",observedFlow:selectedDischarge.observedFlow,observedLoad:selectedDischarge.observedLoad,authorizedLoad:selectedDischarge.authorizedLoad,parameter:"DBO 5,20",authority:regulationContext.authority,evidenceId:fieldContext.evidenceId,due:"15 dias"}}));onToast(`${selectedDischarge.id}: memória conciliada e revisão encaminhada ao M4, sem alterar o ato.`);};
  const approveRecovery=()=>{setMeasures(items=>items.map(item=>item.id==="MED-REC-0041"?{...item,status:"Em execução",progress:28}:item));setRecoveryModalOpen(false);setTargets(items=>items.map(item=>item.segmentId===selectedSegment.id?{...item,status:"Atenção"}:item));window.dispatchEvent(new CustomEvent("cht:quality-recovery-action-event",{detail:{measureId:"MED-REC-0041",planId:planningContext.planId,actionId:planningContext.actionId,projectId:planningContext.projectId,title:"Otimizar remoção de carga e restaurar trecho prioritário",segmentId:selectedSegment.id,territory:selectedSegment.basin,budget:184.6,priority:"P1",benefit:91,targetReduction:31,due:"dez 2030",scenarioId:scenarioContext.scenarioId,center:selectedSegment.center}}));emitTower("Medida de recuperação priorizada","Médio",`Acompanhar ${selectedSegment.id} por metas, contratos M5 e gates do M8.`);onToast("Decisão humana registrada; ação, orçamento indicativo e metas enviados ao M8.");};
  const escalateIncident=()=>{window.dispatchEvent(new CustomEvent("cht:quality-incident-event",{detail:{segmentId:selectedSegment.id,title:`Desconformidade persistente · ${selectedSegment.name}`,territory:selectedSegment.basin,parameter:selectedSample.parameter,observed:selectedSample.observed,limit:selectedSample.limit,unit:selectedSample.unit,confidence:selectedSample.quality,level:selectedSegment.condition==="Não conforme"?"N2":"N1",stationId:selectedSample.stationId,center:selectedSegment.center}}));emitTower("Evento de qualidade escalado para verificação","Alto",`M9 deve verificar persistência e exposição em ${selectedSegment.id} antes de qualquer alerta.`);onToast("Sinal contextual enviado ao M9; nenhum alerta público foi emitido.");};

  const Kpis=()=> <div className="water-kpis"><article><span>TRECHOS AVALIADOS</span><strong>1.284</strong><small>87% com classe e condição</small><i style={{width:"87%"}}/></article><article><span>CONFORMIDADE</span><strong>68,4%</strong><small>↓ 1,8 pt no trimestre</small><i className="warn" style={{width:"68.4%"}}/></article><article><span>AMOSTRAS QUALIFICADAS</span><strong>{2846-liveTick}</strong><small>96,1% em SLA · 24 h</small><i style={{width:"96%"}}/></article><article><span>METAS EM RISCO</span><strong>27</strong><small>11 exigem decisão</small><i className="critical" style={{width:"42%"}}/></article></div>;
  const Situation=()=> <div className="water-situation"><header className="water-toolbar"><div><h2>Situação integrada da qualidade da água</h2><p>Classe, condição observada, tendência, pressão, exposição e resposta em um quadro comum</p></div><div><span className="water-live">● LIVE · {clockLabel} BRT</span><button onClick={requestQualityData}>↻ Atualizar RNQA</button><button className="primary" onClick={startAgent}>✦ Analisar trecho</button></div></header><div className="water-situation-grid"><article className="panel water-map-card"><header className="panel-header"><div><h2>Mapa de condição e enquadramento</h2><p>ArcGIS · BHO6 · RNQA · Living Atlas · uso do solo</p></div><button onClick={()=>focusSegment(selectedSegment)}>Focar ArcGIS ↗</button></header><div className="water-map"><div className="water-map-grid"/><i className="water-river one"/><i className="water-river two"/>{segments.map((item,index)=><button key={item.id} className={`water-pin p${index+1} ${statusClass(item.condition)} ${item.id===selectedSegment.id?"selected":""}`} onClick={()=>focusSegment(item)}><span>{item.iqa}</span><small>{item.id}</small></button>)}<div className="water-map-legend"><span><i className="good"/> conforme</span><span><i className="warn"/> atenção</span><span><i className="bad"/> não conforme</span></div></div><footer><div><small>SELEÇÃO</small><strong>{selectedSegment.name}</strong><span>{selectedSegment.classRef} · IQA {selectedSegment.iqa} · {selectedSegment.confidence}% confiança</span></div><button onClick={()=>onNavigate("Trechos")}>Abrir passaporte do trecho →</button></footer></article><aside className="panel water-alerts"><header className="panel-header"><div><h2>Alertas contextuais</h2><p>persistência, exposição e confiança</p></div><span>4 abertos</span></header>{[["OD abaixo do mínimo","TRC-SF-0418 · 3 janelas","Alto","94%"],["Turbidez pós-cheia","TRC-ITA-0033 · tendência ↓","Médio","89%"],["Carga observada > autorizada","LAN-MG-00741 · +23%","Alto","92%"],["Meta com progresso insuficiente","META-QA-011 · 38%","Alto","91%"]].map(item=><button key={item[0]} onClick={()=>onToast(`${item[0]}: evidências, regra e consumidores carregados.`)}><span className={item[2]==="Alto"?"bad":"warn"}>!</span><div><strong>{item[0]}</strong><small>{item[1]}</small></div><em>{item[2]}</em><b>{item[3]}</b><i>→</i></button>)}<section><span>CADEIA CONECTADA</span><p>M5 observa → M3 interpreta regra → M4 relaciona ato → M6 simula → M7 verifica → M8 recupera → M9 responde.</p></section></aside></div><article className="panel water-source-health"><header className="panel-header"><div><h2>Fontes e contratos operacionais</h2><p>frescor, qualidade, autoridade e latência</p></div><button onClick={()=>openConsumer("m5")}>Abrir Data Hub ↗</button></header>{[["RNQA / laboratórios","2.846 amostras · qv.23","96,1%","18 min","Operacional"],["Órgãos ambientais","enquadramento + licenças","93,8%","2 h","Operacional"],["SNIS / saneamento","cobertura e tratamento","88,4%","D-1","Parcial"],["CAR + uso do solo","pressão difusa · Living Atlas","91,2%","6 h","Operacional"],["M4 · usos e lançamentos","atos, vazões e condicionantes","95,6%","evento","Operacional"]].map(row=><button key={row[0]}><span className={row[4]==="Parcial"?"warn":"good"}/><div><strong>{row[0]}</strong><small>{row[1]}</small></div><b>{row[2]}</b><time>{row[3]}</time><em>{row[4]}</em></button>)}</article></div>;
  const Segments=()=> <div className="water-segments"><header className="water-toolbar"><div><h2>Trechos e passaporte de qualidade</h2><p>Identidade BHO6, classe, condição, conectividade, pressões, população e evidência</p></div><div><button onClick={()=>openConsumer("m1")}>Identidade M1 ↗</button><button className="primary" onClick={()=>focusSegment(selectedSegment)}>⌖ Localizar trecho</button></div></header><div className="water-segment-layout"><article className="panel water-segment-list"><div className="water-list-head"><span>TRECHO / BACIA</span><span>CLASSE</span><span>IQA</span><span>TENDÊNCIA</span><span>CONDIÇÃO</span><span/></div>{segments.map(item=><button key={item.id} className={item.id===selectedSegment.id?"selected":""} onClick={()=>focusSegment(item)}><span className={`water-condition ${statusClass(item.condition)}`}>{item.iqa}</span><div><small>{item.id} · BHO6</small><strong>{item.name}</strong><p>{item.basin}</p></div><span>{item.classRef}<small>{item.targetClass}</small></span><b>{item.iqa}</b><span>{item.trend}</span><em className={statusClass(item.condition)}>{item.condition}</em><i>→</i></button>)}</article><aside className="panel water-segment-passport"><header><div><small>{selectedSegment.id} · CHT-ID vinculado</small><h2>{selectedSegment.name}</h2><p>{selectedSegment.basin}</p></div><em className={statusClass(selectedSegment.condition)}>{selectedSegment.condition}</em></header><div className="water-passport-score"><span><b style={{width:`${selectedSegment.iqa}%`}}/></span><strong>IQA {selectedSegment.iqa}</strong><small>{selectedSegment.confidence}% confiança</small></div>{[["ENQUADRAMENTO",selectedSegment.classRef,selectedSegment.targetClass],["PRESSÃO DOMINANTE",selectedSegment.pressure,"fontes pontuais + difusas"],["EXPOSIÇÃO",selectedSegment.population,"abastecimento e recreação"],["CONECTIVIDADE","12 trechos a montante","8 a jusante · 3 reservatórios"]].map(item=><section key={item[0]}><span>{item[0]}</span><strong>{item[1]}</strong><small>{item[2]}</small></section>)}<footer><button onClick={()=>onNavigate("Enquadramento")}>Ver regra e meta</button><button className="primary" onClick={()=>onNavigate("Qualidade")}>Abrir observações →</button></footer></aside></div><article className="panel water-profile"><header className="panel-header"><div><h2>Perfil longitudinal do trecho</h2><p>condição estimada, estações, lançamentos e confluências · 0–84 km</p></div><span>OD · mg/L</span></header><div className="water-profile-chart"><div className="profile-limit">mínimo classe 2 · 5,0</div><i className="profile-line"/>{[8,22,39,57,78].map((left,index)=><button key={left} style={{left:`${left}%`,bottom:`${[68,51,32,44,61][index]}%`}}><span/><b>{[6.2,5.1,3.6,4.4,5.7][index]}</b><small>{index===2?"RNQA-MG-0174":`P${index+1}`}</small></button>)}<em className="outfall" style={{left:"35%"}}>▼ LAN-MG-00741</em></div></article></div>;
  const Framing=()=> <div className="water-framing"><header className="water-toolbar"><div><h2>Enquadramento, regras e metas progressivas</h2><p>Classe oficial × condição × meta × horizonte, com fonte normativa e decisão humana</p></div><div><button onClick={()=>openConsumer("m3")}>Consultar Motor Regulatório ↗</button><button className="primary" onClick={()=>setFramingModalOpen(true)}>Revisar gap</button></div></header><div className="water-framing-grid"><article className="panel framing-current"><header><small>{selectedSegment.id}</small><h2>Classe 2</h2><p>Resolução CERH-MG nº 32/2024 · vigência validada</p></header><div className="framing-steps">{[["Classe atual","2","oficial"],["Condição","3","equivalente"],["Meta 2030","2","progressiva"]].map((item,index)=><section key={item[0]}><span>{index+1}</span><div><small>{item[0]}</small><strong>{item[1]}</strong><em>{item[2]}</em></div>{index<2&&<i>→</i>}</section>)}</div><div className="framing-gap"><span>GAP PRIORITÁRIO</span><strong>OD +1,4 mg/L · DBO −2,2 mg/L</strong><p>A equivalência é analítica e não substitui a classe definida pela autoridade.</p></div></article><article className="panel framing-matrix"><header className="panel-header"><div><h2>Matriz classe × parâmetro</h2><p>referência demonstrativa · CONAMA 357/2005</p></div><span>versão 2026.08</span></header><div className="framing-matrix-head"><span>PARÂMETRO</span><span>OBSERVADO</span><span>LIMITE</span><span>GAP</span><span>REGRA</span><span>STATUS</span></div>{[["Oxigênio dissolvido","3,6 mg/L","≥ 5,0","−1,4","R-QA-OD-02","Não conforme"],["DBO 5,20","7,2 mg/L","≤ 5,0","+2,2","R-QA-DBO-02","Não conforme"],["Fósforo total","0,086 mg/L","≤ 0,10","−0,014","R-QA-PT-02","Conforme"],["E. coli","824 NMP","≤ 1.000","−176","R-QA-EC-02","Conforme"],["Turbidez","72 NTU","≤ 100","−28","R-QA-TUR-02","Conforme"]].map(row=><button key={row[0]}><strong>{row[0]}</strong>{row.slice(1,5).map(item=><span key={item}>{item}</span>)}<em className={statusClass(row[5])}>{row[5]}</em></button>)}</article></div><article className="panel framing-trace"><header className="panel-header"><div><h2>Trilha de explicação regulatória</h2><p>jurisdição, vigência, regra, dado e ressalva</p></div><span>citável</span></header>{[["01","Resolver competência","União × MG · domínio e delegação","M3 · 98%"],["02","Recuperar enquadramento","trecho BHO6 e geometria de incidência","CERH-MG 32/2024"],["03","Aplicar regra temporal","classe 2 · referência 10 ago 2026","R-QA-OD-02 v8"],["04","Confrontar observação","3,6 ±0,18 mg/L · método SM","M5 · qv.23"],["05","Explicitar limite","inferência não altera ato ou classe","HIL-10"]].map(item=><section key={item[0]}><span>{item[0]}</span><div><strong>{item[1]}</strong><p>{item[2]}</p></div><em>{item[3]}</em></section>)}</article></div>;
  const Quality=()=> <div className="water-quality"><header className="water-toolbar"><div><h2>Amostras, parâmetros e QA/QC laboratorial</h2><p>Bruto imutável, método, limite de detecção, incerteza, flags e versão qualificada</p></div><div><button onClick={()=>openConsumer("m5")}>Séries no M5 ↗</button><button className="primary" onClick={()=>setSampleModalOpen(true)}>＋ Qualificar amostra</button></div></header><div className="water-quality-layout"><article className="panel sample-list"><div className="sample-head"><span>AMOSTRA / ESTAÇÃO</span><span>PARÂMETRO</span><span>OBSERVADO</span><span>LIMITE</span><span>QUALIDADE</span><span>STATUS</span><span/></div>{samples.map(item=><button key={item.id} className={item.id===selectedSample.id?"selected":""} onClick={()=>setSelectedSampleId(item.id)}><span className={`sample-icon ${item.observed>item.limit?"bad":"good"}`}>●</span><div><small>{item.id}</small><strong>{item.stationId}</strong><p>{item.collectedAt} · {item.lab}</p></div><span>{item.parameter}</span><b>{item.observed} {item.unit}</b><span>{item.limit} {item.unit}</span><strong>{item.quality}%</strong><em className={statusClass(item.status)}>{item.status}</em><i>→</i></button>)}</article><aside className="panel sample-detail"><header><div><small>{selectedSample.id}</small><h2>{selectedSample.parameter}</h2><p>{selectedSample.stationId} · {selectedSample.collectedAt}</p></div><em className={selectedSample.observed>selectedSample.limit?"bad":"good"}>{selectedSample.observed>selectedSample.limit?"fora da referência":"dentro da referência"}</em></header><div className="sample-result"><span>RESULTADO</span><strong>{selectedSample.observed} <small>{selectedSample.unit}</small></strong><b>limite {selectedSample.limit} · incerteza {selectedSample.uncertainty}</b></div>{[["MÉTODO",selectedSample.method],["LABORATÓRIO",selectedSample.lab],["VERSÃO / QUALIDADE",`${dataContext.version} · ${selectedSample.quality}%`],["PROVENIÊNCIA",`${dataContext.seriesId} · checksum preservado`]].map(item=><section key={item[0]}><span>{item[0]}</span><strong>{item[1]}</strong></section>)}<footer><button onClick={()=>onToast("Cadeia de custódia, branco, duplicata e calibração carregados.")}>Ver cadeia</button><button className="primary" onClick={()=>setSampleModalOpen(true)}>Revisar QA/QC →</button></footer></aside></div><article className="panel quality-heatmap"><header className="panel-header"><div><h2>Heatmap parâmetro × tempo</h2><p>desvio normalizado da referência · últimas 12 campanhas</p></div><span>jan–ago 2026</span></header>{["OD","DBO","E. coli","Fósforo","Turbidez"].map((name,row)=><div key={name}><strong>{name}</strong>{Array.from({length:12},(_,index)=><i key={index} className={(index+row*2)%7===0?"bad":(index+row)%4===0?"warn":"good"}/>) }<b>{row<2?"piora":"estável"}</b></div>)}</article></div>;
  const Discharges=()=> <div className="water-discharges"><header className="water-toolbar"><div><h2>Lançamentos, cargas e capacidade de assimilação</h2><p>Ato × vazão × concentração × carga observada × tratamento × condição do trecho</p></div><div><button onClick={()=>openConsumer("m4")}>Abrir Regulação de Usos ↗</button><button className="primary" onClick={()=>setDischargeModalOpen(true)}>Reconciliar lançamento</button></div></header><div className="discharge-layout"><article className="panel discharge-table"><div className="discharge-head"><span>LANÇAMENTO / TITULAR</span><span>ATO</span><span>VAZÃO AUT. × OBS.</span><span>CARGA AUT. × OBS.</span><span>TRATAMENTO</span><span>STATUS</span><span/></div>{discharges.map(item=><button key={item.id} className={item.id===selectedDischarge.id?"selected":""} onClick={()=>setSelectedDischargeId(item.id)}><span className={`discharge-icon ${statusClass(item.status)}`}>▼</span><div><small>{item.id} · {item.segmentId}</small><strong>{item.name}</strong><p>{item.holder}</p></div><span>{item.permit}</span><span>{item.authorizedFlow} × <b>{item.observedFlow}</b><small>L/s</small></span><span>{item.authorizedLoad} × <b>{item.observedLoad}</b><small>kg DBO/d</small></span><span>{item.treatment}</span><em className={statusClass(item.status)}>{item.status}</em><i>→</i></button>)}</article><aside className="panel load-balance"><header className="panel-header"><div><h2>Balanço de carga</h2><p>{selectedDischarge.id} · DBO 5,20</p></div><span>+23%</span></header><div className="load-gauge"><i style={{"--load":"77%"} as React.CSSProperties}/><strong>{selectedDischarge.observedLoad}</strong><small>kg/d observados</small></div>{[["AUTORIZADA",`${selectedDischarge.authorizedLoad} kg/d`,61],["OBSERVADA",`${selectedDischarge.observedLoad} kg/d`,77],["ASSIMILÁVEL","2.070 kg/d",69],["META 2030","1.288 kg/d",43]].map(item=><p key={item[0] as string}><span>{item[0]}</span><b>{item[1]}</b><i><em style={{width:`${item[2]}%`}}/></i></p>)}<section><span>CONTEXTO QUANTIDADE × QUALIDADE</span><p>Vazão de referência Q7,10 · 31,8 m³/s · cenário {scenarioContext.scenarioId} · confiança {scenarioContext.reliability}%.</p></section></aside></div></div>;
  const Pressures=()=> <div className="water-pressures"><header className="water-toolbar"><div><h2>Pressões e atribuição de fontes</h2><p>Fontes pontuais, difusas e acidentais correlacionadas com uso do solo, CAR e hidrografia</p></div><div><button onClick={requestQualityScenario}>Simular no M6</button><button className="primary" onClick={startAgent}>✦ Executar atribuição</button></div></header><div className="pressure-layout"><article className="panel pressure-ranking"><div className="pressure-head"><span>FONTE / TIPO</span><span>TERRITÓRIO</span><span>CARGA</span><span>SCORE</span><span>TENDÊNCIA</span><span>CONFIANÇA</span><span>STATUS</span></div>{pressures.map((item,index)=><button key={item.id}><span className={`pressure-rank r${index+1}`}>{index+1}</span><div><small>{item.id} · {item.type}</small><strong>{item.source}</strong></div><span>{item.territory}</span><span>{item.load}</span><b>{item.score}</b><span>{item.trend}</span><strong>{item.confidence}%</strong><em className={statusClass(item.status)}>{item.status}</em></button>)}</article><aside className="panel source-share"><header className="panel-header"><div><h2>Contribuição estimada</h2><p>ensemble de atribuição · P10–P90</p></div><span>91%</span></header><div className="source-donut"><strong>4,12<small>t DBO/d</small></strong></div>{[["Esgoto urbano",56,"#4ed2c4"],["Industrial",18,"#74a9ff"],["Difusa rural",16,"#d9b56f"],["Outras",10,"#778998"]].map(item=><p key={item[0] as string}><i style={{background:item[2] as string}}/><span>{item[0]}</span><b>{item[1]}%</b></p>)}<section><span>LIMITAÇÃO</span><p>Atribuição probabilística; exige confirmação de campo e não presume responsabilidade.</p></section></aside></div><article className="panel pressure-evidence"><header className="panel-header"><div><h2>Evidências territoriais</h2><p>ArcGIS, Living Atlas, CAR/SICAR, SNIS, M4 e M7</p></div><button onClick={()=>openConsumer("m7")}>Solicitar vistoria ↗</button></header>{[["Uso do solo · Living Atlas","18% solo exposto no buffer de 2 km","6 h","91%"],["CAR / SICAR","418 imóveis · 72 APPs com gap","D-1","86%"],["SNIS 2025","coleta 82% · tratamento 71%","anual","93%"],["M4 · lançamentos","41 atos · 7 divergências de carga","evento","96%"],["M7 · campo",`${fieldContext.evidenceId} · ${fieldContext.status}`,"22 min","94%"]].map(row=><button key={row[0]}><span>◇</span><div><strong>{row[0]}</strong><small>{row[1]}</small></div><time>{row[2]}</time><b>{row[3]}</b><i>↗</i></button>)}</article></div>;
  const Targets=()=> <div className="water-targets"><header className="water-toolbar"><div><h2>Metas, indicadores e trajetória</h2><p>Baseline, condição atual, alvo, prazo, fonte, qualidade, progresso e monitoramento</p></div><div><button onClick={requestQualityData}>Contratar indicador no M5</button><button className="primary" onClick={()=>openConsumer("m8")}>Abrir planejamento ↗</button></div></header><div className="target-kpis"><article><span>METAS ATIVAS</span><strong>84</strong><small>7 planos e 21 programas</small></article><article><span>NO PRAZO</span><strong>61%</strong><small>51 metas</small></article><article><span>EM RISCO</span><strong>27</strong><small>11 decisões pendentes</small></article><article><span>COM CONTRATO M5</span><strong>92%</strong><small>77 indicadores</small></article></div><article className="panel target-table"><div className="target-head"><span>META / PARÂMETRO</span><span>BASELINE</span><span>ATUAL</span><span>ALVO</span><span>TRAJETÓRIA</span><span>PRAZO / FONTE</span><span>PROGRESSO</span><span>STATUS</span></div>{targets.map(item=><button key={item.id} onClick={()=>setSelectedSegmentId(item.segmentId)}><span className={`target-icon ${statusClass(item.status)}`}>◎</span><div><small>{item.id} · {item.segmentId}</small><strong>{item.parameter}</strong></div><b>{item.baseline} {item.unit}</b><b>{item.current} {item.unit}</b><b>{item.target} {item.unit}</b><div className="target-mini"><i><em style={{width:`${item.progress}%`}}/></i><small>{item.current>item.target?"redução requerida":"ganho requerido"}</small></div><span>{item.due}<small>{item.source}</small></span><strong>{item.progress}%</strong><em className={statusClass(item.status)}>{item.status}</em></button>)}</article><div className="target-bottom"><article className="panel target-trajectory"><header className="panel-header"><div><h2>Trajetória da meta selecionada</h2><p>observado, esperado e faixa de incerteza</p></div><span>META-QA-011</span></header><div className="trajectory-chart"><i className="trajectory-band"/><i className="trajectory-actual"/><i className="trajectory-target"/>{["2022","2024","2026","2028","2030"].map(year=><span key={year}>{year}</span>)}</div><footer><span><i className="actual"/> observado</span><span><i className="target"/> trajetória pactuada</span><span><i className="band"/> P10–P90</span></footer></article><article className="panel target-contract"><header className="panel-header"><div><h2>Contrato de indicador</h2><p>M5 · observabilidade e qualidade</p></div><em>ativo</em></header>{[["SÉRIE",dataContext.seriesId],["ESTAÇÃO",dataContext.stationId],["MÉTODO","SM 4500-O G · semanal"],["QUALIDADE MÍNIMA","90% · atual 96%"],["FRESCOR","≤ 7 dias · última há 2 h"]].map(item=><p key={item[0]}><span>{item[0]}</span><strong>{item[1]}</strong></p>)}<button onClick={requestQualityData}>Revisar contrato →</button></article></div></div>;
  const Recovery=()=> <div className="water-recovery"><header className="water-toolbar"><div><h2>Portfólio de recuperação e efetividade</h2><p>Medidas, custo, benefício, cenários, responsáveis, evidências, gates e decisão humana</p></div><div><button onClick={requestQualityScenario}>Comparar cenários</button><button className="primary" onClick={()=>setRecoveryModalOpen(true)}>Revisar priorização</button></div></header><div className="recovery-summary"><article><span>INVESTIMENTO INDICATIVO</span><strong>R$ 264,7 mi</strong><small>4 medidas · sem compromisso automático</small></article><article><span>CARGA EVITADA</span><strong>1,42 t/d</strong><small>cenário recomendado · P50</small></article><article><span>GANHO DE IQA</span><strong>+18 pt</strong><small>48 → 66 até 2030</small></article><article><span>BENEFICIÁRIOS</span><strong>2,1 mi</strong><small>abastecimento, recreação e ecossistemas</small></article></div><div className="recovery-layout"><article className="panel recovery-board">{["Proposta","Em pactuação","Em execução","Verificação"].map(status=><section key={status}><header><strong>{status}</strong><span>{measures.filter(item=>item.status===status).length}</span></header>{measures.filter(item=>item.status===status).map(item=><button key={item.id}><small>{item.id} · {item.priority} · {item.kind}</small><strong>{item.title}</strong><p>{item.owner}</p><div><span><i style={{width:`${item.progress}%`}}/></span><b>{item.progress}%</b></div><footer><span>R$ {item.cost} mi</span><em>benefício {item.benefit}</em></footer></button>)}</section>)}</article><aside className="panel recovery-recommendation"><header><div><small>RECOMENDAÇÃO ASSISTIDA · 91%</small><h2>Carteira adaptativa A</h2><p>{scenarioContext.scenarioId} · {scenarioContext.modelId}</p></div><span>1º</span></header>{[["CUSTO","R$ 227,4 mi"],["REDUÇÃO DE CARGA","31% · P50"],["IQA EM 2030","66 · faixa 61–71"],["ROBUSTEZ","84/100"],["REVERSIBILIDADE","76/100"]].map(item=><p key={item[0]}><span>{item[0]}</span><strong>{item[1]}</strong></p>)}<section><span>GATILHOS</span><p>ampliar se OD &lt; 4,2 por 3 campanhas · reprogramar se carga difusa &gt; P75 · revisar anualmente.</p></section><footer><button onClick={()=>onToast("Premissas, ensemble e alternativas B/C carregados.")}>Ver memória</button><button className="primary" onClick={()=>setRecoveryModalOpen(true)}>Decidir →</button></footer></aside></div><article className="panel recovery-effect"><header className="panel-header"><div><h2>Efetividade e contribuição</h2><p>baseline × contrafactual × observado, sem atribuição causal automática</p></div><span>trimestral</span></header>{[["Remoção de DBO","31%","18%","M5 + operador",58],["Restauração ripária","420 ha","244 ha","M7 + Living Atlas",58],["Redução de E. coli","49%","28%","RNQA",57],["Ganho de IQA","+18 pt","+7 pt","M5 · série qv.23",39]].map(item=><section key={item[0] as string}><strong>{item[0]}</strong><span>meta <b>{item[1]}</b></span><span>observado <b>{item[2]}</b></span><span>{item[3]}</span><i><em style={{width:`${item[4]}%`}}/></i><b>{item[4]}%</b></section>)}</article></div>;

  const views:Record<string,()=>ReactNode>={"Situação":Situation,"Trechos":Segments,"Enquadramento":Framing,"Qualidade":Quality,"Lançamentos":Discharges,"Pressões":Pressures,"Metas":Targets,"Recuperação":Recovery}; const ActiveView=views[contextItem]??Situation;
  const agentSteps=["Resolver trecho, classe, vigência e autoridade","Recuperar amostras, séries e QA/QC do M5","Relacionar lançamentos, usos e condicionantes do M4","Correlacionar CAR, uso do solo e evidências M7","Executar atribuição e cenário de cargas no M6","Comparar metas, custos e ações do M8","Redigir achados e medidas para decisão humana"];
  return <section className="water-hub" aria-label={`Qualidade da Água — ${contextItem}`}><div className="water-context-bar"><div><span>QA</span><small>TRECHO / CLASSE</small><strong>{selectedSegment.id} · {selectedSegment.classRef}</strong></div><div><span>◉</span><small>CONDIÇÃO / TENDÊNCIA</small><strong>IQA {selectedSegment.iqa} · {selectedSegment.condition} · {selectedSegment.trend}</strong></div><div><span>◇</span><small>AMOSTRA / QUALIDADE</small><strong>{selectedSample.id} · {selectedSample.quality}%</strong></div><div><span>●</span><small>CONTEXTO OPERACIONAL</small><strong>{territory} · {clockLabel} BRT</strong></div><button onClick={startAgent}>✦ Agente de Qualidade</button></div>{Kpis()}{ActiveView()}
  {sampleModalOpen&&<div className="water-modal-backdrop" onMouseDown={()=>setSampleModalOpen(false)}><section className="water-modal" role="dialog" aria-modal="true" onMouseDown={event=>event.stopPropagation()}><header><div><small>REVISÃO HUMANA · QA/QC</small><h2>Qualificar amostra e desconformidade</h2><p>{selectedSample.id} · bruto preservado · nova versão qualificada</p></div><button onClick={()=>setSampleModalOpen(false)}>×</button></header><div className="water-modal-metrics"><div><span>RESULTADO</span><strong>{selectedSample.observed} {selectedSample.unit}</strong></div><div><span>REFERÊNCIA</span><strong>{selectedSample.limit} {selectedSample.unit}</strong></div><div><span>INCERTEZA</span><strong>{selectedSample.uncertainty}</strong></div><div><span>QUALIDADE</span><strong>{selectedSample.quality}%</strong></div></div><div className="water-modal-grid"><label><span>MÉTODO</span><input defaultValue={selectedSample.method}/></label><label><span>LABORATÓRIO</span><input defaultValue={selectedSample.lab}/></label><label><span>FLAG</span><select defaultValue="desconformidade confirmada"><option>desconformidade confirmada</option><option>resultado suspeito</option><option>recoleta requerida</option></select></label><label><span>VERSÃO DE DESTINO</span><input defaultValue="qv.24 · qualificada"/></label><label className="full"><span>JUSTIFICATIVA DO CURADOR</span><textarea defaultValue="Aceito resultado, método e controles do lote. Registrar desconformidade contextual, incerteza e necessidade de confirmação temporal; preservar o objeto bruto."/></label></div><section className="water-warning"><span>EFEITO CONTROLADO</span><p>Publica versão qualificada e evento interno. Não altera enquadramento, ato, licença ou alerta externo.</p></section><footer><button onClick={()=>setSampleModalOpen(false)}>Cancelar</button><button onClick={()=>{setSampleModalOpen(false);requestQualityData();}}>Solicitar recoleta</button><button className="primary" onClick={qualifySample}>✓ Qualificar e versionar</button></footer></section></div>}
  {framingModalOpen&&<div className="water-modal-backdrop" onMouseDown={()=>setFramingModalOpen(false)}><section className="water-modal" role="dialog" aria-modal="true" onMouseDown={event=>event.stopPropagation()}><header><div><small>DECISÃO HUMANA · ENQUADRAMENTO</small><h2>Validar gap e trajetória progressiva</h2><p>{selectedSegment.id} · regra M3 · condição M5</p></div><button onClick={()=>setFramingModalOpen(false)}>×</button></header><div className="water-modal-metrics"><div><span>CLASSE</span><strong>{selectedSegment.classRef}</strong></div><div><span>CONDIÇÃO</span><strong>equiv. classe 3</strong></div><div><span>META</span><strong>{selectedSegment.targetClass}</strong></div><div><span>CONFIANÇA</span><strong>{selectedSegment.confidence}%</strong></div></div><section><span>INTERPRETAÇÃO</span><p>OD e DBO indicam gap persistente, suportado por três campanhas e pelo cenário de cargas. A equivalência analítica não redefine a classe oficial.</p></section><label className="water-justification"><span>JUSTIFICATIVA DA AUTORIDADE</span><textarea defaultValue="Confirmo o gap para fins de acompanhamento e priorização. Manter classe oficial, fonte normativa, horizonte e revisão anual da trajetória."/></label><footer><button onClick={()=>setFramingModalOpen(false)}>Cancelar</button><button onClick={()=>openConsumer("m3")}>Devolver ao M3</button><button className="primary" onClick={reviewFraming}>✓ Validar acompanhamento</button></footer></section></div>}
  {dischargeModalOpen&&<div className="water-modal-backdrop" onMouseDown={()=>setDischargeModalOpen(false)}><section className="water-modal" role="dialog" aria-modal="true" onMouseDown={event=>event.stopPropagation()}><header><div><small>RECONCILIAÇÃO · M4 + M5</small><h2>Revisar vazão, concentração e carga</h2><p>{selectedDischarge.id} · {selectedDischarge.permit}</p></div><button onClick={()=>setDischargeModalOpen(false)}>×</button></header><div className="water-modal-metrics"><div><span>VAZÃO AUT.</span><strong>{selectedDischarge.authorizedFlow} L/s</strong></div><div><span>VAZÃO OBS.</span><strong>{selectedDischarge.observedFlow} L/s</strong></div><div><span>CARGA AUT.</span><strong>{selectedDischarge.authorizedLoad} kg/d</strong></div><div><span>CARGA OBS.</span><strong>{selectedDischarge.observedLoad} kg/d</strong></div></div><div className="water-modal-grid"><label><span>ATO / CONDICIONANTE</span><input defaultValue={selectedDischarge.permit}/></label><label><span>EVIDÊNCIA DE CAMPO</span><input defaultValue={fieldContext.evidenceId}/></label><label className="full"><span>MEMÓRIA DE CÁLCULO</span><textarea defaultValue="Carga = vazão média validada × concentração DBO qv.23. Desvio de +23% requer checagem de período, representatividade e condição operacional."/></label></div><section className="water-warning"><span>LIMITAÇÃO</span><p>A reconciliação abre revisão no M4; não suspende, altera ou sanciona o ato.</p></section><footer><button onClick={()=>setDischargeModalOpen(false)}>Cancelar</button><button className="primary" onClick={reconcileDischarge}>✓ Encaminhar revisão ao M4</button></footer></section></div>}
  {recoveryModalOpen&&<div className="water-modal-backdrop" onMouseDown={()=>setRecoveryModalOpen(false)}><section className="water-modal recovery-modal" role="dialog" aria-modal="true" onMouseDown={event=>event.stopPropagation()}><header><div><small>DECISÃO HUMANA · PORTFÓLIO</small><h2>Priorizar carteira adaptativa de recuperação</h2><p>{selectedSegment.id} · {scenarioContext.scenarioId} · plano {planningContext.planId}</p></div><button onClick={()=>setRecoveryModalOpen(false)}>×</button></header><div className="water-modal-metrics"><div><span>INVESTIMENTO</span><strong>R$ 227,4 mi</strong></div><div><span>REDUÇÃO</span><strong>31% carga</strong></div><div><span>BENEFÍCIO</span><strong>91/100</strong></div><div><span>CONFIANÇA</span><strong>{scenarioContext.reliability}%</strong></div></div><section><span>CARTEIRA A · RECOMENDADA</span><p>Otimização de ETE + infraestrutura verde + monitoramento sentinela, com gates anuais e reprogramação por tendência.</p></section><div className="decision-triggers"><span>GATES E ROLLBACK</span><p><b>G1 · 2027</b>redução mínima de 12% na carga observada</p><p><b>G2 · 2028</b>OD mediano ≥ 4,2 mg/L por 3 campanhas</p><p><b>Reprogramar</b>benefício &lt; P25 ou custo &gt; 120% do baseline</p></div><label className="water-justification"><span>JUSTIFICATIVA DO COLEGIADO</span><textarea defaultValue="Priorizo a carteira A pela robustez e benefício, condicionada a pactuação, disponibilidade orçamentária e verificação anual das metas."/></label><footer><button onClick={()=>setRecoveryModalOpen(false)}>Cancelar</button><button onClick={()=>{setRecoveryModalOpen(false);requestQualityScenario();}}>Nova simulação</button><button className="primary" onClick={approveRecovery}>✓ Registrar e enviar ao M8</button></footer></section></div>}
  {agentOpen&&<div className="water-agent-backdrop" onMouseDown={()=>setAgentOpen(false)}><aside className="water-agent-drawer" onMouseDown={event=>event.stopPropagation()}><header><div className="water-agent-avatar">✦</div><div><small>{agentRunning?"EXECUÇÃO AO VIVO":"ANÁLISE CONCLUÍDA"}</small><h2>Agente de Qualidade</h2><p>Trace M10-A01-{selectedSegment.id.slice(-4)} · política QA-HIL-010</p></div><button onClick={()=>setAgentOpen(false)}>×</button></header><div className="water-agent-scopes"><span>ESCOPOS</span><b>Consultar</b><b>Correlacionar</b><b>Simular</b><b>Redigir</b><b className="blocked">Decidir ✕</b></div><section className="water-agent-plan"><h3>Plano de execução</h3>{agentSteps.map((item,index)=><div key={item} className={index<agentStep?"done":index===agentStep?"running":"waiting"}><span>{index<agentStep?"✓":index===agentStep?"●":"○"}</span><div><strong>{item}</strong><small>{index<agentStep?`${520+index*218} ms · evidência registrada`:index===agentStep?"executando ferramentas autorizadas…":"aguardando dependência"}</small></div></div>)}</section><section className="water-agent-tools"><h3>Fontes e grounding</h3>{[["M5",`${dataContext.seriesId} · ${dataContext.quality}%`,"observação"],["M3/M4",`${regulationContext.demandId} · ${regulationContext.authority}`,"regra/ato"],["M6",`${scenarioContext.scenarioId} · ${scenarioContext.reliability}%`,"cenário"],["M7",`${fieldContext.evidenceId} · ${fieldContext.status}`,"campo"],["M8",`${planningContext.actionId} · ${planningContext.progress}%`,"recuperação"],["M9",`${incidentContext.incidentId} · ${incidentContext.status}`,"evento"]].map(item=><button key={item[0]}><span>▤</span><div><strong>{item[0]}</strong><small>{item[1]}</small></div><b>{item[2]}</b></button>)}</section><section className="water-agent-output"><div><h3>Saída estruturada</h3><span>92% confiança</span></div><p><b>Fato:</b> OD 3,6 ±0,18 mg/L, abaixo da referência da classe 2 em três campanhas.</p><p><b>Inferência:</b> cargas urbanas explicam a maior parcela do gap, com contribuição difusa relevante.</p><p><b>Recomendação:</b> confirmar persistência, revisar lançamento e priorizar carteira adaptativa A.</p><p><b>Limite:</b> o agente não altera enquadramento, licencia lançamento, sanciona usuário, publica alerta ou decide investimento.</p></section><footer><button onClick={()=>{setAgentRunning(false);onToast("Agente pausado; trace e estado preservados.");}}>■ Pausar</button><button onClick={escalateIncident}>Escalar ao M9</button><button className="primary" onClick={()=>{setAgentOpen(false);setRecoveryModalOpen(true);}}>Revisar recomendação →</button></footer></aside></div>}
  </section>;
}
